"use client";
import { Howl, Howler } from "howler";
import { getMuted, setMutedStored } from "./session";

/** Central sound registry. Files are generated by scripts/gen-sfx.mjs (CC0). */
export const SFX = [
  "hop", "coin", "bad", "match", "perfect", "miss", "reveal", "drumroll", "tick", "win", "fanfare", "star",
  "buy", "steal", "shield", "dice", "click", "whoosh", "countdown", "go", "pop", "lock", "event", "join",
] as const;
export type SfxId = (typeof SFX)[number];

const cache = new Map<string, Howl>();
let initialized = false;

function init() {
  if (initialized || typeof window === "undefined") return;
  initialized = true;
  Howler.mute(getMuted());
}

export function play(id: string, opts: { volume?: number; rate?: number } = {}) {
  if (typeof window === "undefined") return;
  init();
  if (!(SFX as readonly string[]).includes(id)) return;
  let h = cache.get(id);
  if (!h) {
    h = new Howl({ src: [`/sfx/${id}.wav`], volume: 0.6, preload: true });
    cache.set(id, h);
  }
  const sid = h.play();
  if (opts.volume !== undefined) h.volume(opts.volume, sid);
  if (opts.rate !== undefined) h.rate(opts.rate, sid);
}

export function setMuted(m: boolean) {
  init();
  Howler.mute(m);
  setMutedStored(m);
}

export function isMuted() {
  return getMuted();
}

export function vibrate(pattern: number | number[]) {
  try {
    navigator.vibrate?.(pattern);
  } catch {
    /* unsupported */
  }
}
